public static boolean applyDamage(Entity target, float baseAmount, DamageSource damageSource) {
    if (target instanceof LivingEntity livingTarget && damageSource instanceof SpellDamageSource spellDamageSource) {
        var e = new SpellDamageEvent(livingTarget, baseAmount, spellDamageSource);
        if (NeoForge.EVENT_BUS.post(e).isCanceled()) {
            return false;
        }
        baseAmount = e.getAmount();
        float adjustedDamage = baseAmount * getResist(livingTarget, spellDamageSource.spell.getSchoolType());
        if (damageSource.getDirectEntity() instanceof NoKnockbackProjectile) {
            ignoreNextKnockback(livingTarget);
        }
        if (damageSource.getEntity() instanceof LivingEntity livingAttacker) {
            if (isFriendlyFireBetween(livingAttacker, livingTarget)) {
                return false;
            }
            livingAttacker.setLastHurtMob(target);
        }
        return livingTarget.hurt(damageSource, adjustedDamage);
    } else {
        return target.hurt(damageSource, baseAmount);
    }
}

public static boolean isFriendlyFireBetween(@Nullable Entity attacker, @Nullable Entity target) {
    if (attacker == null || target == null) {
        return false;
    }
    if (attacker instanceof IMagicSummon summon) {
        var tmp = summon.getSummoner();
        if (tmp != null) {
            attacker = tmp;
        }
    }
    if (target instanceof IMagicSummon summon) {
        var tmp = summon.getSummoner();
        if (tmp != null) {
            target = tmp;
        }
    }
    if (attacker.isPassengerOfSameVehicle(target)) {
        return true;
    }
    if (attacker instanceof Player playerAttacker && target instanceof Player playertarget
            && !playerAttacker.canHarmPlayer(playertarget)) {
        return true;
    }
    var team = attacker.getTeam();
    if (team != null) {
        return team.isAlliedTo(target.getTeam()) && !team.isAllowFriendlyFire();
    }
    //We already manually checked for teams, so this will only return true for any overrides (such as summons)
    return attacker.isAlliedTo(target);
}

public static void ignoreNextKnockback(LivingEntity livingEntity) {
    if (livingEntity.getServer() != null) {
        var tickCount = livingEntity.getServer().getTickCount();
        //help manage memory
        knockbackImmunes.entrySet().removeIf(entry -> tickCount - entry.getValue() >= 10);
        //enter entity
        knockbackImmunes.put(livingEntity.getUUID(), tickCount);
    }
}

public static void cancelKnockback(LivingKnockBackEvent event) {
    //IronsSpellbooks.LOGGER.debug("DamageSources.cancelKnockback {}", event.getEntity().getName().getString());
    var entity = event.getEntity();
    if (entity.getServer() != null && knockbackImmunes.containsKey(event.getEntity().getUUID())) {
        if (entity.getServer().getTickCount() - knockbackImmunes.get(entity.getUUID()) <= 1) {
            event.setCanceled(true);
        }
        knockbackImmunes.remove(entity.getUUID());
    }
}

public static void postHitEffects(LivingDamageEvent.Post event) {
    var damageSource = event.getSource();
    if (damageSource instanceof SpellDamageSource spellDamageSource && spellDamageSource.hasPostHitEffects()) {
        float actualDamage = event.getNewDamage();
        var target = event.getEntity();
        var attacker = event.getSource().getEntity();
        if (attacker instanceof LivingEntity livingAttacker) {
            if (spellDamageSource.getLifestealPercent() > 0) {
                livingAttacker.heal(spellDamageSource.getLifestealPercent() * actualDamage);
            }
        }
        if (spellDamageSource.getFreezeTicks() > 0 && target.canFreeze()) {
            //Freeze ticks count down by 2, so we * 2 so the spell damages source can be dumb
            target.setTicksFrozen(target.getTicksFrozen() + spellDamageSource.getFreezeTicks() * 2);
        }
        if (spellDamageSource.getFireTime() > 0 && target instanceof LivingEntity) {
            target.igniteForTicks(spellDamageSource.getFireTime());
        }
    }
}

public static void preHitEffects(LivingIncomingDamageEvent event) {
    var damageSource = event.getSource();
    if (damageSource instanceof SpellDamageSource spellDamageSource) {
        if (spellDamageSource.getIFrames() >= 0) {
            event.getContainer().setPostAttackInvulnerabilityTicks(spellDamageSource.getIFrames());
        }
    }
    IMagicSummon fromSummon = damageSource.getDirectEntity() instanceof IMagicSummon summon ? summon : damageSource.getEntity() instanceof IMagicSummon summon ? summon : null;
    if (fromSummon != null) {
        var summoner = fromSummon.getSummoner();
        if (summoner != null && summoner.getUUID().equals(event.getEntity().getUUID())) {
            event.setCanceled(true);
            return;
        }
        if (summoner instanceof LivingEntity livingSummoner) {
            event.setAmount(event.getAmount() * (float) livingSummoner.getAttributeValue(AttributeRegistry.SUMMON_DAMAGE));
        }
    }
}

public static void onLivingIncomingDamage(LivingIncomingDamageEvent event) {
    var livingEntity = event.getEntity();
    //irons_spellbooks.LOGGER.debug("onLivingAttack.1: {}", livingEntity);
    if (event.getSource().getEntity() != null && livingEntity.getVehicle() instanceof IceTombEntity iceTomb && !DamageSources.isFriendlyFireBetween(event.getSource().getEntity(), livingEntity)) {
        // redirect entity-caused damage away from entombed players into the tomb
        event.setCanceled(true);
        iceTomb.hurt(event.getSource(), event.getOriginalAmount());
        return;
    }
    if ((livingEntity instanceof ServerPlayer) || (livingEntity instanceof IMagicEntity)) {
        if (ItemRegistry.FIREWARD_RING.get().isEquippedBy(livingEntity) && event.getSource().is(DamageTypeTags.IS_FIRE)) {
            event.getEntity().clearFire();
            event.setCanceled(true);
            return;
        }
        var playerMagicData = MagicData.getPlayerMagicData(livingEntity);
        if (livingEntity.hasEffect(MobEffectRegistry.EVASION)) {
            if (EvasionEffect.doEffect(livingEntity, event.getSource())) {
                event.setCanceled(true);
                return;
            }
        } else if (livingEntity.hasEffect(MobEffectRegistry.ABYSSAL_SHROUD)) {
            if (AbyssalShroudEffect.doEffect(livingEntity, event.getSource())) {
                event.setCanceled(true);
                return;
            }
        }

        if (livingEntity instanceof ServerPlayer serverPlayer) {
            if (playerMagicData.isCasting() &&
                    playerMagicData.getCastingSpell().getSpell().canBeInterrupted(serverPlayer) &&
                    playerMagicData.getCastDurationRemaining() > 0 &&
                    !event.getSource().is(DamageTypeTagGenerator.LONG_CAST_IGNORE) &&
                    !playerMagicData.popMarkedPoison()) {
                Utils.serverSideCancelCast(serverPlayer);
            }
        }
    }
    if (ServerConfigs.BETTER_CREEPER_THUNDERHIT.get() && event.getSource().is(DamageTypeTags.IS_FIRE) && event.getEntity() instanceof Creeper creeper && creeper.isPowered()) {
        event.setCanceled(true);
        return;
    }
}

public boolean hurt(DamageSource source, float amount) {
    if (!level.isClientSide && health > 0) {
        if (DamageSources.isFriendlyFireBetween(source.getEntity(), this.getFirstPassenger())) {
            return false;
        }
        if (!isInvulnerableTo(source) && (source.getEntity() == null || !isPassengerOfSameVehicle(source.getEntity()))) {
            health -= amount;
            if (health <= 0) {
                die(source, amount);
            }
            return true;
        }
    }
    return super.hurt(source, amount);
}

public void die(DamageSource damageSource, float amount) {
    var entities = getPassengers();
    destroyTomb();
    if (evil) {
        entities.forEach(entity -> entity.hurt(damageSource, amount * 2));
    }
}

