public boolean applyEffectTick(@NotNull LivingEntity pLivingEntity, int pAmplifier) {
    //irons_spellbooks.LOGGER.debug("{} ticks existed: {}", pLivingEntity.getName().getString(), pLivingEntity.tickCount);

    //Heart beats once every 2 seconds at 0% damage, and 2 times per second at 100% damage (relative to health)
    if (pLivingEntity.level.isClientSide) {
        if (pLivingEntity instanceof Player player) {
            float damage = ClientMagicData.getSyncedSpellData(player).getHeartstopAccumulatedDamage();
            float f = 1 - Mth.clamp(damage / player.getHealth(), 0, 1);
            int i = (int) (10 + (40 - 10) * f);
            //Ironsspellbooks.logger.debug("{} ({}/{} = {})", i, damage, player.getHealth(), f);
            if (this.duration % Math.max(i, 1) == 0) {
                player.playSound(SoundEvents.WARDEN_HEARTBEAT, 1, 0.85f);
            }
        }
    }
    return true;

}

public boolean shouldApplyEffectTickThisTick(int pDuration, int pAmplifier) {
    this.duration = pDuration;
    return true;
}

public boolean checkPreCastConditions(Level level, int spellLevel, LivingEntity entity, MagicData playerMagicData) {
    if (Utils.preCastTargetHelper(level, entity, playerMagicData, this, getRange(spellLevel, entity), .15f)) {
        var target = ((TargetEntityCastData) playerMagicData.getAdditionalCastData()).getTarget((ServerLevel) level);
        if (target == null) {
            return false;
        }
        playerMagicData.setAdditionalCastData(new TelekinesisData(entity.distanceTo(target), target, 6));
        return true;
    } else {
        return false;
    }
}

public void onServerCastTick(Level level, int spellLevel, LivingEntity entity, @Nullable MagicData playerMagicData) {
    super.onServerCastTick(level, spellLevel, entity, playerMagicData);
    if (playerMagicData != null && (playerMagicData.getCastDurationRemaining()) % 2 == 0) {
        handleTelekinesis((ServerLevel) level, entity, playerMagicData, .6f);
    }
}

private void handleTelekinesis(ServerLevel world, LivingEntity entity, MagicData playerMagicData, float strength) {
    if (playerMagicData.getAdditionalCastData() instanceof TelekinesisData targetData) {
        var targetEntity = targetData.getTarget(world);
        if (targetEntity != null) {
            if ((targetEntity.isRemoved() || targetEntity.isDeadOrDying()) && entity instanceof ServerPlayer serverPlayer) {
                Utils.serverSideCancelCast(serverPlayer);
                return;
            }
            float resistance = Utils.clampedKnockbackResistanceFactor(entity, .2f, 1f);
            float lockedDistance = targetData.getDistance();
            float actualDistance = entity.distanceTo(targetEntity);
            float distance = Mth.lerp(actualDistance > lockedDistance ? .05f : .02f, lockedDistance, actualDistance);
            targetData.setDistance(distance);
            Vec3 force = (entity.getForward().normalize().scale(targetData.getDistance()).add(entity.position()).subtract(targetEntity.position())).scale(resistance * strength);
            Vec3 travel = new Vec3(targetEntity.getX() - targetEntity.xOld, targetEntity.getY() - targetEntity.yOld, targetEntity.getZ() - targetEntity.zOld);
            if (force.y > 0) {
                targetEntity.resetFallDistance();
            }
            if ((playerMagicData.getCastDurationRemaining()) % 10 == 0) {
                int airborne = (int) (travel.x * travel.x + travel.z * travel.z) / 2;
                targetEntity.addEffect(new MobEffectInstance(MobEffectRegistry.AIRBORNE, 31, airborne, false, false, true));
                targetEntity.addEffect(new MobEffectInstance(MobEffectRegistry.ANTIGRAVITY, 11, 0, false, false, true));
            }
            var deltaMovement = targetEntity.getDeltaMovement();
            var newMotion = force.subtract(deltaMovement).scale(0.25).add(deltaMovement);
            var delta = newMotion.subtract(deltaMovement);
            var clampedMotion = new Vec3(
                    Utils.signedMin(delta.x, force.x * 4),
                    Utils.signedMin(delta.y, force.y * 4),
                    Utils.signedMin(delta.z, force.z * 4)
            );
            targetEntity.setDeltaMovement(deltaMovement.add(clampedMotion));
            targetEntity.hurtMarked = true;
        }
    }
}

public static float clampedKnockbackResistanceFactor(Entity entity, float min, float max) {
    if (entity instanceof LivingEntity living) {
        return Mth.clamp(1 - (float) living.getAttributeValue(Attributes.KNOCKBACK_RESISTANCE), min, max);
    } else {
        return max;
    }
}

public void tick() {
    super.tick();
    this.xo = getX();
    this.yo = getY();
    this.zo = getZ();
    setPos(position().add(getDeltaMovement()));
    int update = Math.max((int) (getRadius() / 2), 2);
    // only query entities at low rate, especially with large hitboxes, and reuse a cached result instead
    if (tickCount % update == 0) {
        updateTrackingEntities();
    }
    var bb = this.getBoundingBox();
    float radius = (float) (bb.getXsize());
    boolean hitTick = this.tickCount % 10 == 0;
    Vec3 center = bb.getCenter();
    handleGravity(center, radius, hitTick);
    handleSpellGriefing(radius, center);
    handleClientEffects(center);
}

private void handleGravity(Vec3 center, float radius, boolean hitTick) {
    for (Entity entity : trackingEntities) {
        if (entity != getOwner() && !DamageSources.isFriendlyFireBetween(getOwner(), entity) && !entity.isSpectator() && !(entity instanceof BlackHole)) {
            float distance = (float) center.distanceTo(entity.position());
            if (distance > radius) {
                continue;
            }
            float f = 1 - distance / radius;
            float scale = f * f * f * f * .25f;
            float resistance = Utils.clampedKnockbackResistanceFactor(entity, .3f, 1f);
            float bossResistance = entity.getType().is(Tags.EntityTypes.BOSSES) ? 0.5f : 1f;
            Vec3 diff = center.subtract(entity.position()).scale(scale * resistance * bossResistance);
            entity.push(diff.x, diff.y, diff.z);
            double dmgRadius = Math.min(2.0, radius / 5.0);
            if (damage > 0 && hitTick && distance < dmgRadius * dmgRadius && canHitEntity(entity)) {
                DamageSources.applyDamage(entity, damage, SpellRegistry.BLACK_HOLE_SPELL.get().getDamageSource(this, getOwner()));
            }
            entity.fallDistance = 0;
        }
    }
}

private void handleClientEffects(Vec3 center) {
    if (!level().isClientSide) {
        if (tickCount > duration) {
            this.discard();
            this.playSound(SoundRegistry.BLACK_HOLE_CAST.get(), getRadius() / 2f, 1);
            MagicManager.spawnParticles(level(), ParticleHelper.UNSTABLE_ENDER, getX(), getY() + getRadius(), getZ(), 200, 1, 1, 1, 1, true);
            for (Entity entity : trackingEntities) {
                if (entity.distanceToSqr(center) < 9) {
                    entity.setDeltaMovement(entity.getDeltaMovement().add(entity.position().subtract(center).normalize().scale(0.5f)));
                    entity.hurtMarked = true;
                }
            }
        } else if ((tickCount - 1) % loopSoundDurationInTicks == 0 && (duration < loopSoundDurationInTicks || tickCount + loopSoundDurationInTicks < duration)) {
            this.playSound(SoundRegistry.BLACK_HOLE_LOOP.get(), getRadius() / 3f, .9f + Utils.random.nextFloat() * .2f);
        }
    }
}

private void updateTrackingEntities() {
    trackingEntities = level().getEntities(this, this.getBoundingBox().inflate(1));
}

public void onCast(Level level, int spellLevel, LivingEntity entity, CastSource castSource, MagicData playerMagicData) {
    if (playerMagicData.getAdditionalCastData() instanceof TargetEntityCastData castTargetingData) {
        LivingEntity target = castTargetingData.getTarget((ServerLevel) level);
        if (target != null && !target.getType().is(ModTags.CANT_ROOT)) {
            Vec3 spawn = target.position();
            float health = getRootHealth(spellLevel, entity);
            RootEntity rootEntity = new RootEntity(level, entity);
            rootEntity.setDuration(getDuration(spellLevel, entity));
            rootEntity.setTarget(target);
            rootEntity.moveTo(spawn);
            rootEntity.getAttribute(Attributes.MAX_HEALTH).setBaseValue(health);
            rootEntity.setHealth(health);
            level.addFreshEntity(rootEntity);
            target.stopRiding();
            target.startRiding(rootEntity, true);
        }
    }

    super.onCast(level, spellLevel, entity, castSource, playerMagicData);
}

public void tick() {
    super.tick();
    if (playSound) {
        this.refreshDimensions();
        playSound(SoundRegistry.ROOT_EMERGE.get(), 2f, 1);
        playSound = false;
    }

    if (!level().isClientSide) {
        if (tickCount % 20 == 0 && this.random.nextFloat() < .5f && this.getFirstPassenger() instanceof Mob mob) {
            mob.setTarget(this);
        }
        if (tickCount > duration || (target != null && target.isDeadOrDying()) || !isVehicle()) {
            this.removeRoot();
        }
    } else {
        if (tickCount < 20) {
            clientDiggingParticles(this);
        }
    }
}

public void positionRider(Entity passenger, Entity.MoveFunction p_19958_) {
    //super.positionRider(pPassenger);
    int x = (int) (this.getX() - passenger.getX());
    int y = (int) (this.getY() - passenger.getY());
    int z = (int) (this.getZ() - passenger.getZ());
    x *= x;
    y *= y;
    z *= z;
    //probably teleported away
    if (x + y + z > 5 * 5) {
        this.removeRoot();
    } else {
        passenger.setPos(this.getX(), this.getY(), this.getZ());
    }
}

public void removeRoot() {
    if (level().isClientSide) {
        for (int i = 0; i < 5; i++) {
            level().addParticle(ParticleHelper.ROOT_FOG, getX() + Utils.getRandomScaled(.1f), getY() + Utils.getRandomScaled(.1f), getZ() + Utils.getRandomScaled(.1f), Utils.getRandomScaled(2f), -random.nextFloat() * .5f, Utils.getRandomScaled(2f));
        }
    }
    if (this.getFirstPassenger() instanceof Mob mob && mob.getTarget() == this) {
        mob.setTarget(null);
    }
    this.ejectPassengers();
    this.discard();
}

