    return false;//super.isPushable() && !isImmobile();
}

public boolean isInvulnerableTo(DamageSource source) {
    return super.isInvulnerableTo(source) || getPose().equals(Pose.EMERGING);
}

protected boolean isImmobile() {
    return super.isImmobile() || getPose().equals(Pose.EMERGING);
}

public void onSyncedDataUpdated(EntityDataAccessor<?> pKey) {
    super.onSyncedDataUpdated(pKey);
    if (pKey == DATA_IS_CROUCHING) {
        refreshDimensions();
        crouchTick = tickCount;
    } else if (pKey == Entity.DATA_POSE) {
        if (this.getPose() == Pose.EMERGING) {
            playAnimation("emerge_from_ground");
            emergeTick = EMERGE_TIME;
        }
    }
}

public boolean hurt(DamageSource pSource, float pAmount) {
    if (level().isClientSide || this.isInvulnerableTo(pSource) || invulnerableTime > 0)
        return false;
    invulnerableTime = 10;
    doPuffDamage();
    spawnIcicleShards(this.getEyePosition(), this.shatterProjectileDamage);
    this.playHurtSound(pSource);
    this.discard();
    return true;
}

public void tick() {
    if (firstTick) {
        if (level.isClientSide) {
            if (cachedSummoner != null) {
                this.walkAnimSpeed = cachedSummoner.walkAnimation.speed();
                this.walkAnimPos = cachedSummoner.walkAnimation.position();
            }
        }
    }
    super.tick();
    if (deathTimer > 0) {
        deathTimer--;
    }
    if (deathTimer == 0) {
        this.hurt(level().damageSources().generic(), 100);
    }
}

private void doPuffDamage() {
    var damage = this.shatterProjectileDamage * .5f;
    var collider = this.getBoundingBox().inflate(2);
    var radius = collider.getXsize();
    Vec3 center = collider.getCenter();
    var entities = level.getEntities(this, collider);
    for (Entity entity : entities) {
        double distanceSqr = entity.distanceToSqr(center);
        if (distanceSqr < radius * radius && entity.canBeHitByProjectile() && !DamageSources.isFriendlyFireBetween(entity, getSummoner()) && Utils.hasLineOfSight(level, center, entity.getBoundingBox().getCenter(), true)) {
            DamageSources.applyDamage(entity, damage, SpellRegistry.ICICLE_SPELL.get().getDamageSource(this, getSummoner()));
        }
    }
    MagicManager.spawnParticles(level, ParticleHelper.SNOW_DUST, getX(), getY() + 1, getZ(), 50, 0.2, 0.2, 0.2, 0.2, false);
    MagicManager.spawnParticles(level, ParticleHelper.SNOWFLAKE, getX(), getY() + 1, getZ(), 50, 0.2, 0.2, 0.2, 0.2, false);
}

private void spawnIcicleShards(Vec3 origin, float damage) {
    int count = 8;
    int offset = 360 / count;
    for (int i = 0; i < count; i++) {

        Vec3 motion = new Vec3(0, 0, 1.0);
        motion = motion.xRot(12 * Mth.DEG_TO_RAD);
        motion = motion.yRot(offset * i * Mth.DEG_TO_RAD);


        IcicleProjectile shard = new IcicleProjectile(level(), getSummoner());
        shard.setDamage(damage);
        shard.setDeltaMovement(motion);
        shard.setNoGravity(false);

        Vec3 spawn = origin.add(motion.multiply(1, 0, 1).normalize().scale(.5f));
        var angle = Utils.rotationFromDirection(motion);

        shard.moveTo(spawn.x, spawn.y - shard.getBoundingBox().getYsize() / 2, spawn.z, angle.y, angle.x);
        level().addFreshEntity(shard);
    }
}

public boolean hurt(DamageSource pSource, float pAmount) {
    if (pSource == level.damageSources().lava()) {
        return false;
    }
    if (pSource.is(DamageTypes.IN_WALL) && this.destroyBlockDelay <= 0) {
        Utils.doMobBreakSuffocatingBlocks(this);
        destroyBlockDelay = 40;
    }
    var entity = pSource.getEntity();
    if (entity != null) {
        float distance = entity.distanceTo(this);
        float damageReduction = Mth.clampedLerp(1, 0.5f, (distance - 8) / 16); // reduce damage from 8-24 blocks away, down to 50%
        pAmount *= damageReduction;
    }
    return super.hurt(pSource, pAmount);
}

public boolean canBeAffected(MobEffectInstance pEffectInstance) {
    return !AlchemistAttackGoal.ATTACK_POTIONS.contains(pEffectInstance.getEffect());
}

public boolean hurt(DamageSource pSource, float pAmount) {
    if (pSource.is(DamageTypes.INDIRECT_MAGIC) && pSource.getEntity() == this) {
        //prevent our own harm potions from affecting us
        return false;
    }
    return super.hurt(pSource, pAmount);
}

protected void doSpellAction() {
    //Instead of taking a normal casting action, there is a chance to attempt a potion action
    if (this.mob.distanceToSqr(this.target) < throwRangeSqr && this.mob.getRandom().nextFloat() < potionBias) {
        int attackWeight = getAttackWeight();
        int supportWeight = getSupportWeight();
        ItemStack potion = new ItemStack(Items.SPLASH_POTION);
        var targetedEntity = target;
        if (hasLineOfSight && mob.getRandom().nextFloat() * (attackWeight + supportWeight) > supportWeight) {
            // We want the potion amplifier to scale with the "difficulty" of our target, with a chunk of randomness. For vanilla players, this will stick to from I-II.
            int amplifier = (mob.getRandom().nextFloat() < 0.75f ? 0 : 1) + (target.getMaxHealth() > 30 ? (mob.getRandom().nextFloat() < 0.5f ? 0 : 1) : 0);
            var effect = target.isInvertedHealAndHarm() ? MobEffects.HEAL : MobEffects.HARM;
            if (mob.getRandom().nextFloat() < 0.45f) {
                //Effect, instead of damage
                for (int i = 0; i < ATTACK_POTIONS.size(); i++) {
                    int p = mob.getRandom().nextInt(ATTACK_POTIONS.size());
                    if (!target.hasEffect(ATTACK_POTIONS.get(p))) {
                        effect = ATTACK_POTIONS.get(p);
                        break;
                    }
                }
            }
            //PotionUtils.setCustomEffects(potion, List.of(new MobEffectInstance(effect, effect.isInstantenous() ? 0 : 200, amplifier)));
            //Utils.setPotion(potion, Potions.WATER); //"Empty" potion skips rendering color. "water" checks for the effect and renders properly
            potion.set(DataComponents.POTION_CONTENTS, new PotionContents(Potions.WATER).withEffectAdded(new MobEffectInstance(effect, effect.value().isInstantenous() ? 0 : 200, amplifier)));
        } else {
            Utils.setPotion(potion, Potions.STRONG_HEALING);
            targetedEntity = this.mob;
        }
        ThrownPotion thrownpotion = new ThrownPotion(this.mob.level, this.mob);
        thrownpotion.setItem(potion);
        thrownpotion.setXRot(thrownpotion.getXRot() - -20.0F);
        Vec3 vec3 = targetedEntity.getDeltaMovement();
        double d0 = targetedEntity.getX() + vec3.x - this.mob.getX();
        double d1 = targetedEntity.getEyeY() - (double) 1.1F - this.mob.getEyeY();
        double d2 = targetedEntity.getZ() + vec3.z - this.mob.getZ();
        double d3 = Math.sqrt(d0 * d0 + d2 * d2);
        thrownpotion.shoot(d0, d1 + d3 * 0.2D, d2, (float) Mth.clampedLerp(0.5f, 1.25f, this.mob.distanceToSqr(targetedEntity) / throwRangeSqr), 8.0F);
        if (!this.mob.isSilent()) {
            this.mob.level.playSound(null, this.mob.getX(), this.mob.getY(), this.mob.getZ(), SoundEvents.WITCH_THROW, this.mob.getSoundSource(), 1.0F, 0.8F + this.mob.getRandom().nextFloat() * 0.4F);
        }
        this.mob.level.addFreshEntity(thrownpotion);
        this.mob.swing(InteractionHand.MAIN_HAND, true);
    } else {
        super.doSpellAction();
    }
}

public boolean hurt(DamageSource pSource, float pAmount) {
    if (!level.isClientSide) {
        if (!parentEntity.hurtThisTick) {
            parentEntity.takeDamage(pSource, pAmount, this.getBoundingBox().getCenter());
            parentEntity.hurtThisTick = true;
        }
    }
    return false;
}

public void takeDamage(DamageSource source, float amount, @Nullable Vec3 location) {
    if (!this.isInvulnerableTo(source)) {
        this.setHealth(this.getHealth() - amount);
        if (!level().isClientSide && location != null) {
            MagicManager.spawnParticles(level(), ParticleTypes.ELECTRIC_SPARK, location.x, location.y, location.z, 30, .1, .1, .1, .5, false);
            level().playSound(null, location.x, location.y, location.z, SoundRegistry.FORCE_IMPACT.get(), SoundSource.NEUTRAL, .8f, 1f);
        }
    }
}

public void tick() {
    hurtThisTick = false;
    if (getHealth() <= 0) {
        destroy();
    } else if (++age > LIFETIME) {
        if (!this.level().isClientSide) {
            level().playSound(null, getX(), getY(), getZ(), SoundEvents.RESPAWN_ANCHOR_SET_SPAWN, SoundSource.NEUTRAL, 1, 1.4f);
        }
        discard();
    } else {
        for (int i = 0; i < subEntities.length; i++) {
            var subEntity = subEntities[i];

            Vec3 pos = subPositions[i].xRot(Mth.DEG_TO_RAD * -this.getXRot()).yRot(Mth.DEG_TO_RAD * -this.getYRot()).add(this.position());
            subEntity.setPos(pos);
            //subEntity.setDeltaMovement(newVector);
            //var vec3 = new Vec3(subEntity.getX(), subEntity.getY(), subEntity.getZ());
            subEntity.xo = pos.x;
            subEntity.yo = pos.y;
            subEntity.zo = pos.z;
            subEntity.xOld = pos.x;
            subEntity.yOld = pos.y;
            subEntity.zOld = pos.z;
        }
    }
}

public boolean hurt(DamageSource source, float amount) {
    if (source.is(DamageTypes.CACTUS) || source.is(DamageTypes.SWEET_BERRY_BUSH) || source.is(DamageTypes.IN_WALL) || source.is(DamageTypes.LAVA) || source.is(DamageTypes.DROWN))
        return false;
    if (source.is(DamageTypes.FREEZE))
        amount = amount / 2;
    if (this.getPhaseSwapping())
        return false;

    Entity entity = source.getEntity();
    if (entity instanceof LivingEntity entity1 && !entity.equals(this)) {
        if (isDefensive() && !source.is(DamageTypes.THORNS)) {
            if (!source.is(DamageTypeTags.BYPASSES_ARMOR) && BlockUtil.distanceFrom(level, entity.position, position) <= 3) {
                entity.hurt(level.damageSources().thorns(this), 6.0f);
            }
        }

        // Omit our summoned sources that might aggro or accidentally hurt us
        if (entity1 instanceof WildenStalker || entity1 instanceof WildenGuardian || entity instanceof WildenHunter
                || entity instanceof ISummon && ((ISummon) entity).getOwnerUUID() != null && ((ISummon) entity).getOwnerUUID().equals(this.getUUID())
                || entity1 instanceof SummonWolf && ((SummonWolf) entity1).isWildenSummon)
            return false;
    }

    if (isDefensive())
        return false;
    var threshold = this.getMaxHealth() / 4;
    var nextMin = this.getMaxHealth() - threshold * (1 + getPhase());
    boolean res = super.hurt(source, amount);
    if (!this.level.isClientSide && this.getHealth() <= nextMin && getPhase() < 3) {
        this.setPhaseSwapping(true);
        this.setPhase(this.getPhase() + 1);
        this.getNavigation().stop();
        this.setHealth(nextMin);
        this.dead = false;
        this.setFlying(false);
        this.setDefensiveMode(false);
        isRamGoal = false;
    }
    return res;
}

public boolean canBeAffected(MobEffectInstance instance) {
    MobEffect effect = instance.getEffect().value();
    if (instance.getEffect() instanceof SnareEffect)
        return false;

    if (effect == MobEffects.MOVEMENT_SLOWDOWN)
        instance = new MobEffectInstance(instance.getEffect(), 1, 0);

    if (effect == ModPotions.GRAVITY_EFFECT.get())
        instance = new MobEffectInstance(instance.getEffect(), Math.min(instance.getDuration(), 100), 0);
    return super.canBeAffected(instance);
}

default void applyPotion(LivingEntity entity, Holder<MobEffect> potionEffect, SpellStats stats, int baseDurationSeconds, int durationBuffSeconds, boolean showParticles) {
    if (entity == null)
        return;
    int ticks = baseDurationSeconds * 20 + durationBuffSeconds * stats.getDurationInTicks();
    int amp = (int) stats.getAmpMultiplier();
    entity.addEffect(new MobEffectInstance(potionEffect, ticks, amp, false, showParticles, true));
}

public void onResolveEntity(EntityHitResult rayTraceResult, Level world, @NotNull LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
    super.onResolveEntity(rayTraceResult, world, shooter, spellStats, spellContext, resolver);
    int ticksToRewind = getRewindTicks(spellStats);
    Entity entity = rayTraceResult.getEntity();
    if (!entity.getType().is(EntityTags.REWIND_BLACKLIST) && entity instanceof IRewindable rewindable && !rewindable.isRewinding()) {
        var delayEvent = new DelayedSpellEvent(ticksToRewind, rayTraceResult, world, resolver);
        spellContext.delay(delayEvent);
        EventQueue.getServerInstance().addEvent(new RewindEvent(entity, world.getGameTime(), ticksToRewind, spellContext));
        if (rewindable instanceof Player player) {
            Networking.sendToNearbyClient(world, player, new PacketClientRewindEffect(ticksToRewind, player));
        }

        EventQueue.getServerInstance().addEvent(delayEvent);
    }
}

public static boolean shouldRecordData(Entity entity, IRewindable rewindable) {
    if (entity.level.isClientSide && !(entity instanceof Player)) {
        return false;
    }
    if (!EffectRewind.INSTANCE.isEnabled() || entity.getType().is(EntityTags.REWIND_BLACKLIST)) {
        return false;
    }
    return !rewindable.isRewinding();
}

