public void onResolveEntity(EntityHitResult rayTraceResult, Level world, @NotNull LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {

    float strength = (float) (GENERIC_DOUBLE.get() + AMP_VALUE.get() * spellStats.getAmpMultiplier());
    knockback(rayTraceResult.getEntity(), spellContext.getCaster(), strength, spellStats.hasBuff(AugmentExtract.INSTANCE));
    rayTraceResult.getEntity().hurtMarked = true;

}

public void knockback(Entity target, @NotNull IWrappedCaster shooter, float strength, boolean fromCaster) {
    if (fromCaster) {
        Vec3 vec3 = shooter.getPosition().subtract(target.position());
        vec3 = vec3.normalize();
        knockback(target, strength, vec3.x, vec3.z);
        return;
    }
    float v = 0;
    if (shooter instanceof TileCaster tc) {
        BlockEntity tile = tc.getTile();
        if (tile instanceof RotatingTurretTile rotatingTurretTile) {
            v = rotatingTurretTile.getRotationY();
        } else if (tile instanceof BasicSpellTurretTile || tile instanceof RuneTile) {
            v = tile.getBlockState().getValue(FACING).toYRot();
        }
    } else if (shooter instanceof LivingCaster lc) v = lc.livingEntity.yRot;
    knockback(target, strength, Mth.sin(v * ((float) Math.PI / 180F)), -Mth.cos(v * ((float) Math.PI / 180F)));
}

public void knockback(Entity entity, double strength, double xRatio, double zRatio) {
    if (entity instanceof LivingEntity living)
        strength *= 1.0D - living.getAttributeValue(Attributes.KNOCKBACK_RESISTANCE);
    if (strength > 0.0D) {
        entity.hasImpulse = true;
        Vec3 vec3 = entity.getDeltaMovement();
        Vec3 vec31 = (new Vec3(xRatio, 0.0D, zRatio)).normalize().scale(strength);
        entity.setDeltaMovement(vec3.x / 2.0D - vec31.x, entity.onGround() ? Math.min(0.4D, vec3.y / 2.0D + strength) : vec3.y, vec3.z / 2.0D - vec31.z);
    }
}

default boolean attemptDamage(Level world, @NotNull LivingEntity shooter, SpellStats stats, SpellContext spellContext, SpellResolver resolver, Entity entity, DamageSource source, float baseDamage) {
    if (!canDamage(shooter, stats, spellContext, resolver, entity))
        return false;
    ServerLevel server = (ServerLevel) world;
    float totalDamage = (float) (baseDamage + stats.getDamageModifier() + (shooter.getAttributes().hasAttribute(PerkAttributes.SPELL_DAMAGE_BONUS) ?
            shooter.getAttributeValue(PerkAttributes.SPELL_DAMAGE_BONUS) : 0));

    //randomize damage buff or debuff
    if (stats.isRandomized())
        totalDamage += randomRolls(stats, server);

    ///Make sure your DamageSource is an instance of SpellDamageSource,made with [#source(LevelAccessor , ResourceKey)] or manually,
    ///The luck augment will be used during loot generation [LootItemRandomChanceWithEnchantedBonusConditionMixin] and [EnchantedCountIncreaseFunctionMixin]
    if (source instanceof DamageUtil.SpellDamageSource spellSource) {
        spellSource.setLuckLevel(stats.getBuffCount(AugmentFortune.INSTANCE));
    }

    SpellDamageEvent.Pre preDamage = new SpellDamageEvent.Pre(source, shooter, entity, totalDamage, spellContext);
    NeoForge.EVENT_BUS.post(preDamage);

    source = preDamage.damageSource;
    totalDamage = preDamage.damage;
    if (totalDamage <= 0 || preDamage.isCanceled())
        return false;

    if (!entity.hurt(source, totalDamage)) {
        return false;
    }

    shooter.setLastHurtMob(entity);

    SpellDamageEvent.Post postDamage = new SpellDamageEvent.Post(source, shooter, entity, totalDamage, spellContext);
    NeoForge.EVENT_BUS.post(postDamage);

    return true;
}

default boolean canDamage(LivingEntity shooter, SpellStats stats, SpellContext spellContext, SpellResolver resolver, @NotNull Entity entity) {
    return !(entity instanceof LivingEntity living && living.getHealth() <= 0 || entity.isAlliedTo(shooter));
}

public void onResolveEntity(@NotNull EntityHitResult rayTraceResult, Level world, @NotNull LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
    var dispelEvent = NeoForge.EVENT_BUS.post(new DispelEvent.Pre(rayTraceResult, world, shooter, spellStats, spellContext));
    if (dispelEvent.isCanceled())
        return;
    if (rayTraceResult.getEntity() instanceof LivingEntity entity) {
        Collection<MobEffectInstance> effects = entity.getActiveEffects();
        MobEffectInstance[] array = effects.toArray(new MobEffectInstance[0]);
        Optional<HolderSet.Named<MobEffect>> blacklist = world.registryAccess().registryOrThrow(Registries.MOB_EFFECT).getTag(PotionEffectTags.DISPEL_DENY);
        Optional<HolderSet.Named<MobEffect>> whitelist = world.registryAccess().registryOrThrow(Registries.MOB_EFFECT).getTag(PotionEffectTags.DISPEL_ALLOW);
        for (MobEffectInstance e : array) {
            if (e.getCures().contains(EffectCures.MILK)) {
                if (blacklist.isPresent() && blacklist.get().stream().anyMatch(effect -> effect.value() == e.getEffect()))
                    continue;
                entity.removeEffect(e.getEffect());
            } else if (whitelist.isPresent() && whitelist.get().stream().anyMatch(effect -> effect.value() == e.getEffect())) {
                entity.removeEffect(e.getEffect());
            }
        }
        if (!entity.isAlive() || entity.getHealth() <= 0 || entity.isRemoved()) {
            //TODO dispel loot table?
            return;
        }
        if (entity instanceof IDispellable iDispellable) {
            iDispellable.onDispel(shooter);
        }
        NeoForge.EVENT_BUS.post(new DispelEvent.Post(rayTraceResult, world, shooter, spellStats, spellContext));
    }
}

public void onResolveEntity(EntityHitResult rayTraceResult, Level world, @NotNull LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
    if (!(rayTraceResult.getEntity() instanceof LivingEntity livingEntity && world instanceof ServerLevel level))
        return;
    Vec3 vec = safelyGetHitPos(rayTraceResult);
    float damage = (float) (DAMAGE.get() + AMP_VALUE.get() * spellStats.getAmpMultiplier());
    int snareSec = (int) (POTION_TIME.get() + EXTEND_TIME.get() * spellStats.getDurationMultiplier());

    if (!canDamage(livingEntity))
        return;
    this.damage(vec, level, shooter, livingEntity, spellStats, spellContext, resolver, snareSec, damage);
    spawnIce(shooter, level, BlockPos.containing(vec.x, vec.y + (rayTraceResult.getEntity().onGround() ? 1 : 0), vec.z), spellStats, spellContext, resolver);
    if (livingEntity.hasEffect(ModPotions.FREEZING_EFFECT)) {
        livingEntity.setTicksFrozen(livingEntity.getTicksRequiredToFreeze() + 3);
    }
}

public boolean canDamage(LivingEntity livingEntity) {
    return livingEntity.isInWaterOrRain() || livingEntity.hasEffect(MobEffects.MOVEMENT_SLOWDOWN) || livingEntity.getPercentFrozen() > 0.0;
}

public void damage(Vec3 vec, ServerLevel world, LivingEntity shooter, LivingEntity livingEntity, SpellStats stats, SpellContext context, SpellResolver resolver, int snareTime, float damage) {
    if (attemptDamage(world, shooter, stats, context, resolver, livingEntity, buildDamageSource(world, shooter), damage)) {
        world.sendParticles(ParticleTypes.SPIT, vec.x, vec.y + 0.5, vec.z, 50,
                ParticleUtil.inRange(-0.1, 0.1), ParticleUtil.inRange(-0.1, 0.1), ParticleUtil.inRange(-0.1, 0.1), 0.3);

        livingEntity.addEffect(new MobEffectInstance(ModPotions.SNARE_EFFECT, 20 * snareTime));
    }
}

public void spawnIce(Level level, BlockPos pos, BlockPos targetPos, Vec3 scaleVec, SpellStats spellStats, SpellContext context, SpellResolver resolver, LivingEntity shooter) {
    level.setBlock(pos, Blocks.AIR.defaultBlockState(), 3);
    IceShardEntity fallingBlock = new IceShardEntity(level, pos.getX() + 0.5, pos.getY(), pos.getZ() + 0.5, Blocks.ICE.defaultBlockState(), resolver);
    // Send the falling block the opposite direction of the target
    fallingBlock.setDeltaMovement(pos.getX() - targetPos.getX(), pos.getY() - targetPos.getY(), pos.getZ() - targetPos.getZ());
    fallingBlock.setDeltaMovement(fallingBlock.getDeltaMovement().multiply(scaleVec));
    fallingBlock.cancelDrop = true;
    fallingBlock.dropItem = false;
    fallingBlock.hurtEntities = true;
    fallingBlock.baseDamage = ((float) (DAMAGE.get() + AMP_VALUE.get() * spellStats.getAmpMultiplier())) * 0.5f;
    fallingBlock.shooter = shooter;
    level.addFreshEntity(fallingBlock);
    ShapersFocus.tryPropagateEntitySpell(fallingBlock, level, shooter, context, resolver);
}

public void onResolveEntity(EntityHitResult rayTraceResult, Level world, @NotNull LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
    if (!(rayTraceResult.getEntity() instanceof LivingEntity livingEntity && world instanceof ServerLevel level))
        return;
    Vec3 vec = safelyGetHitPos(rayTraceResult);
    float damage = (float) (DAMAGE.get() + AMP_VALUE.get() * spellStats.getAmpMultiplier());

    if (!canDamage(livingEntity))
        return;
    this.damage(vec, level, shooter, livingEntity, spellStats, spellContext, resolver, damage);
    spawnCinders(shooter, level, rayTraceResult.getLocation().add(0, (rayTraceResult.getEntity().onGround() ? 1 : 0), 0), spellStats, spellContext, resolver);

    if (rayTraceResult.getEntity() instanceof LivingEntity living && living.hasEffect(ModPotions.BLAST_EFFECT)) {
        int amplifier = living.getEffect(ModPotions.BLAST_EFFECT).getAmplifier();
        living.removeEffect(ModPotions.BLAST_EFFECT);
        BlastEffect.explode(living, amplifier + 1);
    }
}

public boolean canDamage(LivingEntity livingEntity) {
    return livingEntity.isOnFire() || livingEntity.hasEffect(ModPotions.BLAST_EFFECT) || livingEntity.level.getBlockState(livingEntity.blockPosition()).is(BlockTags.FIRE);
}

public void damage(Vec3 vec, ServerLevel world, LivingEntity shooter, LivingEntity livingEntity, SpellStats stats, SpellContext context, SpellResolver resolver, float damage) {
    if (attemptDamage(world, shooter, stats, context, resolver, livingEntity, buildDamageSource(world, shooter), damage)) {
        world.sendParticles(ParticleTypes.CAMPFIRE_COSY_SMOKE, vec.x, vec.y + 0.5, vec.z, 50,
                ParticleUtil.inRange(-0.1, 0.1), ParticleUtil.inRange(-0.1, 0.1), ParticleUtil.inRange(-0.1, 0.1), 0.3);
