}

public void onResolveEntity(EntityHitResult rayTraceResult, Level world, @NotNull LivingEntity shooter, SpellStats spellStats, SpellContext spellContext, SpellResolver resolver) {
    if (rayTraceResult.getEntity() instanceof LivingEntity living) {
        if (spellStats.hasBuff(AugmentExtendTime.INSTANCE)) {
            this.applyConfigPotion(living, ModPotions.GRAVITY_EFFECT, spellStats);
        } else {
            Entity entity = rayTraceResult.getEntity();
            entity.setDeltaMovement(entity.getDeltaMovement().add(0, -1.0 - spellStats.getAmpMultiplier(), 0));
            entity.hurtMarked = true;
        }
    }
}

public boolean applyEffectTick(LivingEntity livingEntity, int p_76394_2_) {
    if (!livingEntity.onGround()) {
        boolean isTooHigh = true;
        Level world = livingEntity.level;
        if (livingEntity instanceof Player) {
            for (int i = 1; i < 3; i++) {
                if (!world.getBlockState(livingEntity.blockPosition().below(i)).isAir()) {
                    isTooHigh = false;
                    break;
                }
            }
        }
        if (isTooHigh) {
            livingEntity.setDeltaMovement(livingEntity.getDeltaMovement().add(0, -0.5, 0));
            livingEntity.hurtMarked = true;
        }

    }

    return true;
}

public static void entityTick(PlayerTickEvent.Post e) {
    if (e.getEntity().hasEffect(ModPotions.GRAVITY_EFFECT) && !e.getEntity().onGround() && !e.getEntity().isCreative()) {
        e.getEntity().abilities.flying = false;
    }
}

public static void entityHurt(LivingDamageEvent.Pre e) {
    var container = e.getContainer();
    var source = container.getSource();
    var amount = container.getNewDamage();
    if (source.is(DamageTypes.FALL) && e.getEntity().hasEffect(ModPotions.GRAVITY_EFFECT)) {
        container.setNewDamage(amount * 2.0f);
    }
}

public void tick(boolean serverSide) {
    this.serverSide = serverSide;
    if (!this.registeredEvents && this.serverSide) {
        if (entity instanceof ServerPlayer) {
            NeoForge.EVENT_BUS.addListener(this::onEntityRemoved);
        }
        NeoForge.EVENT_BUS.addListener(this::onChangeDimension);
        this.registeredEvents = true;
    }
    long eventGameTime = startGameTime - this.rewindTicks;
    if (entity instanceof IRewindable rewindable) {
        rewindable.setRewinding(true);
        if (!rewindable.getMotions().empty()) {
            RewindEntityData data = rewindable.getMotions().pop();
            data.onRewind(this);
        }
    }
    if (context != null) {
        RewindAttachment rewindAttachment = RewindAttachment.get(context);
        List<IRewindCallback> contextData = rewindAttachment.getForTime(eventGameTime);
        // Lock and prevent adding rewind events for the current tick. Otherwise you get CME or infinte loops
        rewindAttachment.setLockedTime(eventGameTime);
        if (contextData != null) {
            for (IRewindCallback callback : contextData) {
                callback.onRewind(this);
            }
        }
        rewindAttachment.setLockedTime(-1);
    }
    rewindTicks++;
    if (rewindTicks >= ticksToRewind) {
        stop();
    }
}

public void stop() {
    doneRewinding = true;
    if (entity instanceof IRewindable rewindable) {
        rewindable.setRewinding(false);
        entity.setDeltaMovement(Vec3.ZERO);
        this.removeWeightlessness();
    }
}

public void onChangeDimension(EntityTravelToDimensionEvent event) {
    if (entity == null) {
        NeoForge.EVENT_BUS.unregister(this);
        return;
    }

    if (!event.isCanceled() && entity == event.getEntity() && event.getEntity() instanceof IRewindable rewindable) {
        rewindable.getMotions().clear();
    }
}

public void onEntityRemoved(PlayerEvent.PlayerLoggedOutEvent event) {
    if (entity == null) {
        NeoForge.EVENT_BUS.unregister(this);
        return;
    }

    if (entity == event.getEntity()) {
        this.removeWeightlessness();
        NeoForge.EVENT_BUS.unregister(this);
    }
}

public void removeWeightlessness() {
    if (!respectsGravity) {
        return;
    }

    if (entity instanceof LivingEntity le) {
        var weight = le.getAttribute(PerkAttributes.WEIGHT);
        if (weight != null) {
            weight.removeModifier(ArsNouveau.prefix("rewind"));
        }
    } else if (entity != null) {
        entity.setNoGravity(false);
    }
}

public static boolean preCastTargetHelper(Level level, LivingEntity caster, MagicData playerMagicData, AbstractSpell spell, int range, float aimAssist, boolean sendFailureMessage, Predicate<LivingEntity> filter) {
    var target = RaycastBuilder.begin(caster.level, caster)
            .range(range)
            .checkForBlocks(true)
            .bbInflation(aimAssist)
            .build();
    LivingEntity livingTarget = null;
    if (target instanceof EntityHitResult entityHit) {
        if (entityHit.getEntity() instanceof PreventDismount) {
            if (entityHit.getEntity().getFirstPassenger() instanceof LivingEntity livingRooted) {
                livingTarget = livingRooted;
            }
        } else if (entityHit.getEntity() instanceof LivingEntity livingEntity && filter.test(livingEntity)) {
            livingTarget = livingEntity;
        } else if (entityHit.getEntity() instanceof PartEntity<?> partEntity &&
                partEntity.getParent() instanceof LivingEntity livingParent && !caster.equals(livingParent)
                && filter.test(livingParent)) {
            livingTarget = livingParent;
        }
    }

    if (livingTarget != null) {
        playerMagicData.setAdditionalCastData(new TargetEntityCastData(livingTarget));
        if (caster instanceof ServerPlayer serverPlayer) {
            if (spell.getCastType() != CastType.INSTANT) {
                PacketDistributor.sendToPlayer(serverPlayer, new SyncTargetingDataPacket(livingTarget, spell));
            }
            serverPlayer.connection.send(new ClientboundSetActionBarTextPacket(Component.translatable("ui.irons_spellbooks.spell_target_success", livingTarget.getDisplayName().getString(), spell.getDisplayName(serverPlayer)).withStyle(ChatFormatting.GREEN)));
        }
        if (livingTarget instanceof ServerPlayer serverPlayer) {
            Utils.sendTargetedNotification(serverPlayer, caster, spell);
        }
        return true;
    } else if (sendFailureMessage && caster instanceof ServerPlayer serverPlayer) {
        serverPlayer.connection.send(new ClientboundSetActionBarTextPacket(Component.translatable("ui.irons_spellbooks.cast_error_target").withStyle(ChatFormatting.RED)));
    }
    return false;
}

public static void sendTargetedNotification(ServerPlayer target, LivingEntity caster, AbstractSpell spell) {
    target.connection.send(new ClientboundSetActionBarTextPacket(Component.translatable("ui.irons_spellbooks.spell_target_warning", caster.getDisplayName().getString(), spell.getDisplayName(target)).withStyle(ChatFormatting.LIGHT_PURPLE)));
}

